            raise InvalidInput("bad admin/peer")
        rates = _validate_link_state_rates(event["rates"])
        modes = _validate_link_state_modes(event["modes"])
        result.append((t, port, admin, peer, rates, modes))
    return result


def link_state(events, ports, delay):
    """link-state 公共入口：精确签名不变，返回 {"results": [...]}，无 observer。

    record/replay 所需的逐事件观察逻辑封装在内部 _link_state_run 中。
    """
    return _link_state_run(events, ports, delay, observer=None)


def _link_state_run(events, ports, delay, observer=None):
    if observer is not None:  # record：逐事件记录 applied 与对应 results 项
        observer["items"] = []
    caps = {name: (rates, modes) for name, rates, modes in ports}
    # 生效状态：("down",)/("bad",)/("up", rate, mode)；两状态初始皆 false
    committed = {name: ("down",) for name, _, _ in ports}
    pending = {}  # name -> (rate, mode, deadline)；仅 up 目标需协商
    results = []
    for t, port, admin, peer, rates, modes in events:
        # 先完成截止 <= t 的协商
        for name in [
            name
            for name, (_, _, deadline) in pending.items()
            if deadline <= t
        ]:
            rate, mode, _ = pending.pop(name)
            committed[name] = ("up", rate, mode)
        # 再替换该口并计算目标
        if not admin or not peer:
            target = ("down",)
        else:
            local_rates, local_modes = caps[port]
            common_rates = [r for r in local_rates if r in rates]
            common_modes = [m for m in local_modes if m in modes]
            if not common_rates or not common_modes:
                target = ("bad",)
            else:
                target = (
                    "up",
                    max(common_rates),
                    "full" if "full" in common_modes else "half",
                )
        current = pending.get(port)
        effective = (
            ("up", current[0], current[1])
            if current is not None
            else committed[port]
        )
        if target == effective:
            applied = False  # 未变不重置
        elif target[0] == "up":
            # 目标变化即进入 wait 并于 t+delay 完成
            pending[port] = (target[1], target[2], t + delay)
            applied = True
        else:
            # down/bad 立即生效
            pending.pop(port, None)
            committed[port] = target
            applied = True
        current = pending.get(port)
        if current is not None:
            state, rate, mode = "wait", None, None
        else:
            now = committed[port]
            if now[0] == "up":
                state, rate, mode = "up", now[1], now[2]
            else:
                state, rate, mode = now[0], None, None
        results.append(
            {"t": t, "port": port, "state": state, "rate": rate, "mode": mode}
        )
        if observer is not None:
            observer["items"].append(
                {"kind": "link", "t": t, "applied": applied,
                 "output": results[-1]}
            )
    return {"results": results}


def link_state_work(events, ports, delay, limit):
    """link-state 的工作量预演：独立 committed/pending 状态，无副作用。

    W 初值 0；逐事件在完成截止 <= t 的协商前，令 Q 为 pending 数，累计
    Q+1；再沿用 link_state 规则完成到期项、替换该口状态并计算
    down/bad/up 目标，目标未变不重置，变为 up 则进入 wait。等于上限
    合法，首次超过即抛 LinkWorkLimit，不访问后续事件。
    """
    caps = {name: (rates, modes) for name, rates, modes in ports}
    committed = {name: ("down",) for name, _, _ in ports}
    pending = {}  # name -> (rate, mode, deadline)
    work = 0
    for t, port, admin, peer, rates, modes in events:
        work += len(pending) + 1
        if work > limit:
            raise LinkWorkLimit()
        for name in [
            name
            for name, (_, _, deadline) in pending.items()
            if deadline <= t
        ]:
            rate, mode, _ = pending.pop(name)
            committed[name] = ("up", rate, mode)
        if not admin or not peer:
            target = ("down",)
        else:
            local_rates, local_modes = caps[port]
            common_rates = [r for r in local_rates if r in rates]
            common_modes = [m for m in local_modes if m in modes]
            if not common_rates or not common_modes:
                target = ("bad",)
            else:
                target = (
                    "up",
                    max(common_rates),
                    "full" if "full" in common_modes else "half",
                )
        current = pending.get(port)
        effective = (
            ("up", current[0], current[1])
            if current is not None
            else committed[port]
        )
        if target == effective:
            pass  # 未变不重置
        elif target[0] == "up":
            pending[port] = (target[1], target[2], t + delay)
        else:
            pending.pop(port, None)
            committed[port] = target


